const ENV_CONFIG: &str = r#"
app_name: EnvTest
settings:
  environments:
    staging:
      detect:
        - env: BIVVY_TEST_STAGING
          value: "1"
      default_workflow: staging
      provided_requirements:
        - postgres-server
steps:
  always:
    command: echo always
  ci_only:
    command: echo ci-only
    only_environments: [ci]
  dev_only:
    command: echo dev-only
    only_environments: [development]
  with_env_override:
