    #[test]
    fn dry_run_includes_hooks_in_output() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("npm install");
        step.before = vec!["echo setting up".to_string()];
        step.after = vec!["echo cleaning up".to_string()];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            dry_run: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();
        let output = result.output.unwrap();

        assert!(output.contains("npm install"), "output: {}", output);
        assert!(
            output.contains("echo setting up"),
            "before hook missing: {}",
            output
        );
        assert!(
            output.contains("echo cleaning up"),
            "after hook missing: {}",
            output
        );
    }

    #[test]
    fn dry_run_includes_env_in_output() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("cargo build");
        step.env
            .insert("RUST_LOG".to_string(), "debug".to_string());

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            dry_run: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();
        let output = result.output.unwrap();

        assert!(output.contains("RUST_LOG"), "env missing: {}", output);
    }

    #[test]
    fn dry_run_does_not_execute_hooks() {
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("hook-ran.txt");

        let mut step = make_step("echo main");
        step.before = vec![format!("touch {}", marker.display())];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            dry_run: true,
            ..Default::default()
        };

        execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(
            !marker.exists(),
            "hook should not execute in dry-run mode"
        );
    }

    #[test]
    fn format_duration_formats_correctly() {
        assert_eq!(format_duration(Duration::from_millis(500)), "500ms");
        assert_eq!(format_duration(Duration::from_secs(5)), "5.0s");
        assert_eq!(format_duration(Duration::from_secs(65)), "1m 5s");
    }
}

