// Dry run mode
if options.dry_run {
    let command = resolve_string(&step.command, context)?;
    let mut lines = vec![format!("Would run: {}", command)];

    for hook in &step.before {
        let resolved = resolve_string(hook, context)?;
        lines.push(format!("  Before hook: {}", resolved));
    }
    for hook in &step.after {
        let resolved = resolve_string(hook, context)?;
        lines.push(format!("  After hook: {}", resolved));
    }
    if !step.env.is_empty() {
        let mut keys: Vec<&String> = step.env.keys().collect();
        keys.sort();
        lines.push(format!(
            "  Environment: {}",
            keys.iter()
                .map(|k| format!("{}={}", k, step.env[*k]))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    return Ok(StepResult::success(
        &step.name,
        Duration::ZERO,
        None,
        Some(lines.join("\n")),
    ));
}

